#!/usr/bin/env python3
"""Line-oriented targeted IFC parser. No recursive tokenizer."""
import re, sys, math, json
from collections import defaultdict

IFC = '/filesystem/final_batch4__electrical_task8_electrical_specs__blind/50_bim/BLDG4410-E_RevC.ifc'

def read_records(path):
    recs=[]; buf=[]
    for line in open(path,encoding='utf-8'):
        s=line.rstrip('\n')
        if s.startswith('DATA;') or s.startswith('ENDSEC;') or s.startswith('END-ISO'):
            if buf: recs.append(''.join(buf)); buf=[]
            continue
        if s=='' : continue
        if s.startswith('HEADER') or s.startswith('ENDSEC') or s.startswith('END-ISO'): continue
        # accumulate
        buf.append(s)
        if s.endswith(';'):
            recs.append(''.join(buf)); buf=[]
    return recs

# helpers to extract references / strings / numbers from a token string token
REF=re.compile(r'#(\d+)')
def refs_in(tok):
    return [int(x) for x in REF.findall(tok)]

def split_top(s):
    """Split a STEP arg list (without outer parens) into top-level tokens by comma,
    respecting () and '' . Returns list of token strings."""
    toks=[]; depth=0; ins=False; cur=[]; i=0; n=len(s)
    while i<n:
        c=s[i]
        if c=="'":
            ins=not ins; cur.append(c)
        elif not ins:
            if c=='(' : depth+=1; cur.append(c)
            elif c==')': depth-=1; cur.append(c)
            elif c==',' and depth==0:
                toks.append(''.join(cur).strip()); cur=[]
            else:
                cur.append(c)
        else:
            cur.append(c)
        i+=1
    if cur: toks.append(''.join(cur).strip())
    return toks

def strip_str(tok):
    tok=tok.strip()
    if tok.startswith("'") and tok.endswith("'") and len(tok)>=2:
        return tok[1:-1].replace("''","'")
    return None
def is_ref(tok): return tok.startswith('#')
def num(tok):
    tok=tok.strip()
    try: return float(tok)
    except: return None

def main():
    recs=read_records(IFC)
    # Build entity table: id -> (type, [arg tokens])
    E={}
    for r in recs:
        m=re.match(r'#(\d+)=(IFC[A-Z0-9]+)\((.*)\);\s*$',r,re.S)
        if not m: continue
        eid=int(m.group(1)); et=m.group(2)
        args=split_top(m.group(3))
        E[eid]=(et,args)
    print(f"entities {len(E)}",file=sys.stderr,flush=True)

    # cartesian points: id -> [x,y,z]
    P={}
    for eid,(et,a) in E.items():
        if et=='IFCCARTESIANPOINT':
            inner=a[0].strip()
            P[eid]=[num(x) for x in split_top(inner[1:-1]) if x not in ('',)]
    # axis2placement: id -> origin point
    AX={}
    for eid,(et,a) in E.items():
        if et in ('IFCAXIS2PLACEMENT3D','IFCAXIS2PLACEMENT2D'):
            p=refs_in(a[0])
            AX[eid]=P.get(p[0],[0,0,0]) if p else [0,0,0]
    # local placement: id -> (parent, axis2placement)
    LP={}
    for eid,(et,a) in E.items():
        if et=='IFCLOCALPLACEMENT':
            par=refs_in(a[0]); par=par[0] if par else None
            ax=refs_in(a[1]); ax=ax[0] if ax else None
            LP[eid]=(par,ax)
    def placement_loc(pid):
