    def pds_reps(eid):
        if eid not in E: return []
        _,a=E[eid]
        r=refs_in(a[2])  # 3rd arg is list of reps
        return r
    def rep_items(eid):
        if eid not in E: return []
        _,a=E[eid]
        return refs_in(a[3])  # 4th arg items list
    def rep_kind(eid):
        return E[eid][0] if eid in E else None

