    for eid,(et,a) in E.items():
        if et=='IFCRELCONTAINEDINSPATIALSTRUCTURE':
            items=refs_in(a[5]); structs=refs_in(a[6])
            for it in items:
                for s in structs: space_storey[it]=s
    spaces=[]
    for eid,(et,a) in E.items():
        if et=='IFCSPACE':
            name=strip_str(a[6]) if len(a)>6 else None
            refv=obj_reference(eid)
            pid=refs_in(a[5])[0] if refs_in(a[5]) else None
            loc=placement_loc(pid)
            rep=refs_in(a[6])[0] if refs_in(a[6]) else None
            xdim=ydim=height=None
            if rep is not None:
                for sr in pds_reps(rep):
                    for it in rep_items(sr):
                        if it not in E: continue
                        e2,a2=E[it]
                        if e2=='IFCEXTRUDEDAREASOLID':
                            prof=refs_in(a2[0])
                            depth=num(a2[3]) if len(a2)>3 else None
                            if prof and prof[0] in E:
                                p3,a3=E[prof[0]]
                                if p3=='IFCRECTANGLEPROFILEDEF':
                                    xdim=num(a3[3]); ydim=num(a3[4])
                            height=depth
            st=space_storey.get(eid)
            spaces.append(dict(ref=refv,name=name,storey_z=storey_z.get(st),loc=loc,xdim=xdim,ydim=ydim,height=height,eid=eid))

    # LUMINAIRES
    lums=[]
    for eid,(et,a) in E.items():
        if et=='IFCLIGHTFIXTURE':
            typ=strip_str(a[4]) if len(a)>4 else None
            if not typ and len(a)>7: typ=strip_str(a[7])
            pid=refs_in(a[5])[0] if refs_in(a[5]) else None
            loc=placement_loc(pid)
            lums.append(dict(type=typ,loc=loc,eid=eid))
    def in_sp(lf,sp):
        if sp['xdim'] is None: return False
        ox,oy=sp['loc'][0],sp['loc'][1]
        x,y=lf['loc'][0],lf['loc'][1]
        return (ox-sp['xdim']/2-2)<=x<=(ox+sp['xdim']/2+2) and (oy-sp['ydim']/2-2)<=y<=(oy+sp['ydim']/2+2)
    for lf in lums:
        lf['space']=None
