            c=P.get(p,[0,0,0])
            if prev is not None:
                tot+=math.sqrt(sum((c[k]-prev[k])**2 for k in range(min(len(c),len(prev)))))
            prev=c
        return tot

    # FEEDER segments
    seg={}
    for eid,(et,a) in E.items():
        if et=='IFCCABLECARRIERSEGMENT':
            nm=strip_str(a[2]); trade=strip_str(a[7])
            rep=refs_in(a[6])[0] if refs_in(a[6]) else None
            L=0.0
            if rep is not None:
                for sr in pds_reps(rep):
                    for it in rep_items(sr):
                        if it not in E: continue
                        e2,a2=E[it]
                        if e2=='IFCPOLYLINE': L+=poly_len(it)
                        elif e2=='IFCSWEPTDISKSOLID':
                            dr=refs_in(a2[0])
                            if dr and dr[0] in E and E[dr[0]][0]=='IFCPOLYLINE':
                                L+=poly_len(dr[0])
            seg[eid]=dict(name=nm,trade=trade,L=L,ftag=obj_reference(eid))
    feeds=defaultdict(lambda: defaultdict(list))
    for eid,info in seg.items():
        f=info['ftag']
        if f is None: continue
        parts=(info['name'] or '').split('-')
        rn=parts[2] if len(parts)>=4 and parts[0]=='CND' else '1'
        feeds[f][rn].append(eid)
    feeders={}
    for f,runs in feeds.items():
        rlens={rn:sum(seg[s]['L'] for s in segs) for rn,segs in runs.items()}
        seg0=runs[list(runs)[0]][0] if runs else None
        trade=seg[seg0]['trade'] if seg0 else None
        feeders[f]=dict(nrace=len(runs),routed_ft=max(rlens.values())/304.8,trade=trade,raceway_ft={rn:round(v/304.8,3) for rn,v in rlens.items()})
    out=dict(spaces=spaces,luminaires=lums,feeders=feeders)
    json.dump(out,open('ifc_out.json','w'),indent=1,default=str)
    print("spaces",len(spaces),"lums",len(lums),"feeders",len(feeders),file=sys.stderr,flush=True)

if __name__=='__main__':
    main()

