def insert_project_values(out, part_articles_count, secnum):
    """Append a PROJECT-SPECIFIC REQUIREMENTS article to the end of PART 1."""
    if secnum not in SECTION_VALUES: return out
    title, stmts = SECTION_VALUES[secnum]
    # numbering: article 1.(N+1) where N = count of existing articles in PART 1
    num = f"1.{part_articles_count+1}"
    out.append((f"{num} {title}", True))
    for i,s in enumerate(stmts):
        out.append((f"{letters(i+1)}.  {s}", False))
    return out

def make_section_paragraphs(secfile, secnum):
    raw=open(os.path.join(SPECS_DIR,secfile),encoding='windows-1252').read()
    body=raw[raw.find('</HDR>')+len('</HDR>'):]
    toks=tokenize(body)
    p=Parser(toks)
    root=p.parse()
    out=[]  # list of (text, bold)
    # find SCN, STL, DTE at top level
    scn=stl=dte=None
    parts=[]
    for node in root:
        if node.get('tag')=='SCN': scn=node_text(node)
        elif node.get('tag')=='STL': stl=node_text(node)
        elif node.get('tag')=='DTE': dte=node_text(node)
        elif node.get('tag')=='PRT': parts.append(node)
    # header
    num=re.sub(r'\s+',' ',(scn or '').strip())
    out.append((num, True))
    out.append(((stl or '').strip(), True))
    out.append((f"Date: {dte}" if dte else "Date: 08/2025", True))
    out.append(("", False))
    # parts
    for pi,part in enumerate(parts,1):
        ttl=[node_text(c) for c in part['children'] if c.get('tag')=='TTL']
        ttl=ttl[0] if ttl else f"PART {pi}   GENERAL"
        out.append((ttl, True))
        spts=[c for c in part['children'] if c.get('tag')=='SPT']
        if not spts:
            out.append(("Not used.", False))
        art_idx=0
        for node in part['children']:
            if node.get('tag')=='SPT':
                art_idx+=1
                emit_article(node, f"{pi}.{art_idx}", out, depth=0)
    out.append(("", False))
    out.append(("-- End of Section --", True))
    # final cleanup: strip any remaining dangling brackets
    cleaned=[]
    for text,bold in out:
        text=text.replace('[','').replace(']','')
        text=re.sub(r'\s+([.,;:])', r'\1', text)
        text=re.sub(r'\s{2,}',' ',text).strip()
        cleaned.append((text,bold))
    return cleaned

def emit_article(node, num, out, depth):
    ttl=[node_text(c) for c in node['children'] if c.get('tag')=='TTL']
    if ttl:
        out.append((f"{num} {ttl[0]}", True))
    sub_idx=0
    for c in node['children']:
        t=c.get('tag')
        if t in ('TTL',): continue
        if t=='SPT':
            sub_idx+=1
            emit_article(c, f"{num}.{sub_idx}", out, depth+1)
        elif t=='TXT':
            txt=node_text(c)
            if txt: out.append((txt, False))
        elif t=='OLG':
            emit_list(c, num, out, level=1)
        elif t=='LST':
            emit_list(c, num, out, level=1)
        elif t=='REF':
            emit_refs(c, out)
        elif t=='#tai':
            txt=resolve_brackets(strip_inline(collect_text(c)))
            if txt: out.append((txt, False))
        elif t=='#text':
            pass

def emit_list(node, num, out, level):
    idx=0
    markers={1:lambda i:f"{letters(i+1)}.",2:lambda i:f"({i+1})",3:lambda i:f"({letters(i+1)})",4:lambda i:f"{i+1}."}
    for c in node['children']:
        t=c.get('tag')
        if t in ('OLI','ITM'):
            lvl_m=re.search(r'LEVEL="(\d+)"',c.get('attrs',''))
            lvl=int(lvl_m.group(1)) if lvl_m else level
            mk=markers.get(lvl, markers[4])
            txt_parts=[]; nested=[]
            for cc in c['children']:
                if cc.get('tag') in ('OLG','LST'): nested.append(cc)
                elif cc.get('tag')=='#tai': txt_parts.append(collect_text(cc))
                elif cc.get('tag')=='#text': txt_parts.append(cc['text'])
                elif cc.get('tag')=='BRK': txt_parts.append(' ')
                else: txt_parts.append(collect_text(cc))
            raw=''.join(txt_parts)
            txt=resolve_brackets(strip_inline(raw))
            marker=mk(idx)
            out.append((f"{marker}.  {txt}".strip() if txt else marker, False))
            idx+=1
            for nl in nested:
                emit_list(nl, num, out, lvl+1)
        elif t=='#text':
            pass

def emit_refs(node, out):
    org=None
    pending=[]
    for c in node['children']:
        t=c.get('tag')
        if t=='ORG':
            org=node_text(c); out.append((org, False))
        elif t=='RID':
            pending.append(node_text(c))
        elif t=='RTL':
            rid=pending.pop(0) if pending else ''
            rtl=node_text(c)
            out.append((f"   {rid} {rtl}".strip(), False))
        elif t=='#text':
            pass

