            if t[0]=='open' and t[1]=='TAI':
                opt=re.search(r'OPT="([^"]*)"',t[2]); optv=opt.group(1) if opt else ''
                self.pos+=1; inner=self.collect_until('TAI')
                if 'ARMY' in optv: sub.append({'tag':'#tai','children':inner})
                continue
            if t[0]=='close' and t[1]==name:
                d-=1
                if d==0: self.pos+=1; break
                self.pos+=1
            elif t[0]=='text':
                if t[1].strip(): sub.append({'tag':'#text','text':t[1]})
