#!/usr/bin/env python3
"""Parse UFGS SpecsIntact .SEC XML -> tailored project section paragraphs -> .docx."""
import re, os, sys
import docx_writer

SPECS_DIR='/filesystem/final_batch4__electrical_task8_electrical_specs__blind/20_guide_specifications/UFGS_Division_26_SpecsIntact'
OUT='/filesystem/final_batch4__electrical_task8_electrical_specs__blind/output/specs'
os.makedirs(OUT,exist_ok=True)

TAG=re.compile(r'<(/?)([A-Z][A-Z0-9]*)([^>]*)>')
def tokenize(s):
    toks=[]; i=0
    for m in TAG.finditer(s):
        if m.start()>i: toks.append(('text',s[i:m.start()]))
        attrs=m.group(3)
        if m.group(1)=='/':
            toks.append(('close', m.group(2), attrs))
        elif attrs.rstrip().endswith('/'):
            toks.append(('empty', m.group(2), attrs))
        else:
            toks.append(('open', m.group(2), attrs))
        i=m.end()
    if i<len(s): toks.append(('text',s[i:]))
    return toks

def strip_inline(text):
    """Remove MET content, drop inline tags, keep text. BRK->space."""
    # drop <MET>...</MET> content
    text=re.sub(r'<MET\b[^>]*>.*?</MET>','',text,flags=re.S)
    text=TAG.sub('',text)  # drop all tags, keep text
    text=text.replace('\r',' ')
    text=re.sub(r'[ \t]+',' ',text)
    text=re.sub(r'\s*\n\s*',' ',text)
    return text.strip()

PROJECT_CHOICES={}
def choose_option(opts):
    for o in opts:
        tl=o.lower()
        if 'copper' in tl: return o.strip()
    for o in opts:
        tl=o.lower()
        if '480' in tl or '480y' in tl: return o.strip()
    for o in opts:
        if o.strip(): return o.strip()
    return ''

def find_choices(s):
    spans=[]; depth=0; start=None
    for i,c in enumerate(s):
        if c=='[':
            if depth==0: start=i
            depth+=1
        elif c==']':
            depth-=1
            if depth==0 and start is not None:
                spans.append((start,i+1)); start=None
    return spans

CONTEXT_FILLS=[
 # 26 32 15 EG schedule project data
 (re.compile(r'\[Prime\]\[Limited Running Time\]\[Emergency Standby\]\s*\[Industrial\]'), 'Emergency Standby'),
