                sub=self.collect_until(name)
                children.append({'tag':name,'attrs':attrs,'children':sub})
        return children
    def collect_until(self,name):
        sub=[]; d=1
        while self.pos<len(self.toks) and d>0:
            t=self.toks[self.pos]
            if t[0]=='empty':
                if t[1]=='BRK': sub.append({'tag':'BRK'})
