                if t[1].strip(): children.append({'tag':'#text','text':t[1]})
                self.pos+=1
            elif t[0]=='close':
                self.pos+=1; break
            elif t[0]=='empty':
                if t[1]=='BRK': children.append({'tag':'BRK'})
                self.pos+=1
            elif t[0]=='open':
                name=t[1]; attrs=t[2]
                if name=='NTE':
