            grp=[(a,b)]; j=i+1
            while j<len(spans):
                pa,pb=spans[j]
                if '[' in text[pa+1:pb-1]: break
                if re.fullmatch(r'\s*',text[b:pa]):
                    grp.append((pa,pb)); b=pb; j+=1
