    if secnum not in SECTION_VALUES: return out
    title, stmts = SECTION_VALUES[secnum]
    # numbering: article 1.(N+1) where N = count of existing articles in PART 1
    num = f"1.{part_articles_count+1}"
    out.append((f"{num} {title}", True))
    for i,s in enumerate(stmts):
