                text=text[:grp[0][0]]+choose_option(opts)+text[grp[-1][1]:]
                changed=True; break
            i+=1
    text=re.sub(r'\[_+\s*[^\]]*\]','',text)
    while '[' in text:
        new=re.sub(r'\[([^\[\]]*)\]',r'\1',text)
        if new==text: break
