    def parse_block(self, container, cattr):
        children=[]
        while self.pos<len(self.toks):
            t=self.toks[self.pos]
            if t[0]=='text':
                if t[1].strip(): children.append({'tag':'#text','text':t[1]})
                self.pos+=1
            elif t[0]=='close':
                self.pos+=1; break
            elif t[0]=='empty':
                if t[1]=='BRK': children.append({'tag':'BRK'})
                self.pos+=1
            elif t[0]=='open':
                name=t[1]; attrs=t[2]
                if name=='NTE':
                    self.skip('NTE'); continue
                if name=='TAI':
                    opt=re.search(r'OPT="([^"]*)"',attrs)
                    optv=opt.group(1) if opt else ''
                    self.pos+=1
                    sub=self.collect_until('TAI')
                    if 'ARMY' in optv:
                        children.append({'tag':'#tai','children':sub})
                    continue
                self.pos+=1
                sub=self.collect_until(name)
                children.append({'tag':name,'attrs':attrs,'children':sub})
        return children
    def collect_until(self,name):
        sub=[]; d=1
        while self.pos<len(self.toks) and d>0:
            t=self.toks[self.pos]
            if t[0]=='empty':
                if t[1]=='BRK': sub.append({'tag':'BRK'})
                self.pos+=1; continue
            if t[0]=='open' and t[1]=='NTE':
                self.skip('NTE'); continue
            if t[0]=='open' and t[1]=='TAI':
                opt=re.search(r'OPT="([^"]*)"',t[2]); optv=opt.group(1) if opt else ''
                self.pos+=1; inner=self.collect_until('TAI')
                if 'ARMY' in optv: sub.append({'tag':'#tai','children':inner})
                continue
            if t[0]=='close' and t[1]==name:
                d-=1
                if d==0: self.pos+=1; break
                self.pos+=1
            elif t[0]=='text':
                if t[1].strip(): sub.append({'tag':'#text','text':t[1]})
                self.pos+=1
            elif t[0]=='open':
                self.pos+=1; sub.append({'tag':t[1],'attrs':t[2],'children':self.collect_until(t[1])})
            else:
                self.pos+=1
        return sub
    def skip(self,name):
        self.pos+=1; d=1
        while self.pos<len(self.toks) and d>0:
            t=self.toks[self.pos]
            if t[0]=='open' and t[1]==name: d+=1
            elif t[0]=='close' and t[1]==name: d-=1
            self.pos+=1

def collect_text(node):
    """Collect all text from a node and children, with inline handling."""
    if node['tag']=='#text': return node['text']
    if node['tag']=='MET': return ''
    if node['tag']=='BRK': return ' '
    if node['tag']=='#tai':
