def make_section_paragraphs(secfile, secnum):
    global _CUR_SEC
    _CUR_SEC=secnum
    raw=open(os.path.join(SPECS_DIR,secfile),encoding='windows-1252').read()
    body=raw[raw.find('</HDR>')+len('</HDR>'):]
    toks=tokenize(body)
    p=Parser(toks)
    root=p.parse()
    out=[]  # list of (text, bold)
    # find SCN, STL, DTE at top level
    scn=stl=dte=None
    parts=[]
    for node in root:
        if node.get('tag')=='SCN': scn=node_text(node)
        elif node.get('tag')=='STL': stl=node_text(node)
        elif node.get('tag')=='DTE': dte=node_text(node)
        elif node.get('tag')=='PRT': parts.append(node)
    # header
    num=re.sub(r'\s+',' ',(scn or '').strip())
    out.append((num, True))
    out.append(((stl or '').strip(), True))
    out.append((f"Date: {dte}" if dte else "Date: 08/2025", True))
    out.append(("", False))
    # parts
    for pi,part in enumerate(parts,1):
        ttl=[node_text(c) for c in part['children'] if c.get('tag')=='TTL']
        ttl=ttl[0] if ttl else f"PART {pi}   GENERAL"
        out.append((ttl, True))
        spts=[c for c in part['children'] if c.get('tag')=='SPT']
        if not spts:
            out.append(("Not used.", False))
        art_idx=0
        for node in part['children']:
            if node.get('tag')=='SPT':
                art_idx+=1
                emit_article(node, f"{pi}.{art_idx}", out, depth=0)
        if pi==1:
            out=insert_project_values(out, art_idx, secnum)
    out.append(("", False))
